ZIP_RATIO_CAP = 100
ZERO_WIDTH = dict.fromkeys(map(ord, '\u200b\u200c\u200d\u2060\ufeff'), None)

def extract(body, mime_hint, app):
    kind = sniff(bytes(body[:4096]))                 # magic bytes, not extension
    if kind in ('docx', 'pptx', 'xlsx', 'zip'):
        check_expansion(body, ZIP_RATIO_CAP)         # tricky part: before opening
    raw = run_sandboxed(EXTRACTORS[kind], body, timeout=60, mem_mb=1024)
    out = []
    for el in raw:
        t = unicodedata.normalize('NFC', el['text']).translate(ZERO_WIDTH)
        t = ''.join(c for c in t if c in '\n\t' or unicodedata.category(c) != 'Cc')
        t = VOLATILE.sub('', t)                       # render stamps, session ids
        if t.strip():
            out.append({**el, 'text': t})
    if kind == 'pdf' and avg_chars_per_page(out) < 50:
        out = run_sandboxed(ocr_extractor, body, timeout=60, mem_mb=1024)
    return ExtractResult(out, *links_and_people(out))

def check_expansion(body, cap):
    with zipfile.ZipFile(io.BytesIO(body)) as z:
        total = sum(i.file_size for i in z.infolist())
    if total / max(len(body), 1) > cap:
        raise Rejected('zip ratio')

