def chunk_elements(elements, target=400, overlap=40, min_tokens=128):
    sections, cur, path = [], [], []
    for i, el in enumerate(elements):
        hard = el['type'] == 'heading' or starts_new_turn(el, cur, gap_min=10)
        if hard and cur:
            sections.append((list(path), cur)); cur = []
        if el['type'] == 'heading':
            path = path[:el['level'] - 1] + [el['text']]
        cur.append((i, el))
    if cur:
        sections.append((list(path), cur))
    pieces = []
    for path, els in sections:
        pieces += split_section(path, els, target, overlap)   # paragraph, sentence, token
    merged = []
    for p in pieces:                                          # tricky part: tiny pieces
        if merged and p['tokens'] < min_tokens and merged[-1]['path'] == p['path']:
            merged[-1] = join(merged[-1], p)
        else:
            merged.append(p)
    return [Chunk(chunk_id=xxhash.xxh64(m['text']).hexdigest(), text=m['text'],
                  position=n, heading_path=m['path'], token_count=m['tokens'],
                  element_range=m['range']) for n, m in enumerate(merged)]

# split_section never cuts inside a table row or a code line and adds no
# overlap across a hard boundary (heading or turn gap).

