URL_RX = re.compile(r'https?://|www\.', re.I)

async def write_context(tenant_id, doc_text, chunk):
    key = (tenant_id, chunk.chunk_hash, hash64(chunk.heading_path))
    row = await db.fetchrow('SELECT context_line FROM ctx_cache WHERE tenant_id=$1 AND chunk_hash=$2 AND heading_path_hash=$3', *key)
    if row:
        return ContextResult(chunk.chunk_id, row['context_line'], True, False)
    try:
        r = await gateway.chat(
            model=CTX_MODEL, timeout=15,
            messages=[
              {'role': 'system', 'content': [{'type': 'text', 'text': SITUATE_PROMPT},
                  # same prefix for every chunk of this document, marked cacheable
                  {'type': 'text', 'text': '<document>' + doc_text + '</document>',
                   'cache_control': {'type': 'ephemeral'}}]},
              {'role': 'user', 'content': '<chunk>' + chunk.text + '</chunk>'}])
        line = r.text.strip()
        if len(tokens(line)) > 60 or URL_RX.search(line) or '\n' in line:
            raise BadContext(line[:40])          # tricky part: untrusted model output
    except Exception:
        return ContextResult(chunk.chunk_id, None, False, True)
    await db.execute('INSERT INTO ctx_cache VALUES ($1,$2,$3,$4,$5,now()) ON CONFLICT DO NOTHING', *key, line, CTX_MODEL)
    return ContextResult(chunk.chunk_id, line, False, False)

