RANK = {'public': 0, 'internal': 1, 'confidential': 2, 'restricted': 3}

def shannon(s):
    n = len(s)
    return -sum(c / n * math.log2(c / n) for c in Counter(s).values())

def classify_and_mask(chunk, policy_floor):
    spans = []
    for rule in PATTERNS:                                   # keys, private key headers, ids
        spans += [(m.start(), m.end(), rule.type, 'confidential') for m in rule.rx.finditer(chunk.text)]
    spans += [(m.start(), m.end(), 'card', 'restricted') for m in CARD_RX.finditer(chunk.text)
              if luhn_ok(m.group())]
    for m in TOKEN_RX.finditer(chunk.text):                 # 20+ chars
        if len(m.group()) >= 20 and shannon(m.group()) > 4.5 and not overlaps(spans, m):
            ctx = chunk.text[max(0, m.start() - 100): m.end() + 100]
            if ambiguous_is_secret(ctx):                    # model call, fail closed
                spans.append((m.start(), m.end(), 'high_entropy', 'confidential'))
    label = max([policy_floor] + [s[3] for s in spans], key=RANK.get)
    if label == 'restricted':
        return None
    text = chunk.text
    for a, b, t, _ in sorted(spans, reverse=True):          # tricky part: right to left keeps offsets valid
        text = text[:a] + f'[SECRET:{t}]' + text[b:]
    audit([(chunk.chunk_id, t, r) for _, _, t, r in spans])   # type and rule only, never the value
    return CleanChunk(chunk.chunk_id, text, label, [{'type': t, 'start': a, 'end': b} for a, b, t, _ in spans])

