from pyroaring import BitMap

def ids_for(db, tenant, terms):
    by_kind = {}
    for t in terms:
        by_kind.setdefault(t.kind, []).append(t)
    out = None
    for kind, ts in by_kind.items():
        bm = BitMap()
        for t in ts:
            bm |= load_bitmap(db, tenant, kind, t.value)      # OR within a kind
        out = bm if out is None else out & bm                 # AND across kinds
    return out if out is not None else load_bitmap(db, tenant, "all", "*")
